import pandas as pd
import plotly.express as px
import plotly.graph_objects as go
import streamlit as st
from src.sql_engine import (
    add_spc_control_limits,
    enrich_equipment_stats,
    load_sql_templates,
    run_select_query,
)

st.set_page_config(
    page_title="Fab Yield SQL Analytics | Semiconductor Data Warehouse",
    page_icon="🗄️",
    layout="wide",
)

st.title("🗄️ Fab Yield SQL Analytics — Semiconductor Telemetry & Quality Warehouse")
st.info(
    "**Data Source & Simulation Transparency:** Synthetic star-schema data warehouse (`fab_telemetry.db`) generated by `src/build_db.py` "
    "(`seed=42`, `n=1,200` wafers across 48 lots of 25 wafers). Controlled defect drift (+8% on `CVD-03`, +4% on `Shift-C Night`) "
    "was injected to validate statistical attribution queries; SiliconGuard sensor risk scores and optical detections are simulated at the wafer level."
)

st.sidebar.title("Warehouse Filters & Cost Model")
sel_tools = st.sidebar.multiselect("Filter Equipment (`tool_id`)", list(("CVD-03", "ETCH-01", "LITHO-02", "CMP-04")), default=list(("CVD-03", "ETCH-01", "LITHO-02", "CMP-04")))
sel_shifts = st.sidebar.multiselect("Filter Shift (`shift_id`)", list(("SHIFT-A", "SHIFT-B", "SHIFT-C")), default=list(("SHIFT-A", "SHIFT-B", "SHIFT-C")))
st.sidebar.markdown("---")
st.sidebar.markdown("### Cost Sensitivity Parameters")
scrap_unit_cost = st.sidebar.number_input("Blocked / Scrap Wafer Loss ($)", 1000, 15000, 4500, 250)
quarantine_unit_cost = st.sidebar.number_input("Secondary Lab Quarantine Cost ($)", 100, 2000, 400, 50)

if not sel_tools or not sel_shifts:
    st.warning("Please select at least one equipment ID and one shift in the sidebar.")
    st.stop()

tools_in = ", ".join(list((f"'{t}'" for t in sel_tools)))
shifts_in = ", ".join(list((f"'{s}'" for s in sel_shifts)))

df_raw = run_select_query(f"""
    SELECT f.*, e.process_step, e.chamber_model, e.target_yield_pct, e.target_rationale, s.shift_label
    FROM fact_wafer_inspection f
    JOIN dim_equipment e ON f.tool_id = e.tool_id
    JOIN dim_shift s ON f.shift_id = s.shift_id
    WHERE f.tool_id IN ({tools_in}) AND f.shift_id IN ({shifts_in})
""")

df_raw["dynamic_cost_usd"] = df_raw["routing_decision"].map(
    {"BLOCK_PACKAGING": float(scrap_unit_cost), "SECONDARY_LAB_CHECK": float(quarantine_unit_cost), "RELEASE": 0.0}
)

tot_wafers = len(df_raw)
passed_wafers = int(df_raw["is_passed"].sum())
overall_yield = round(100.0 * passed_wafers / max(tot_wafers, 1), 2)
tot_cost = float(df_raw["dynamic_cost_usd"].sum())

equip_grp = (
    df_raw.groupby(list(("tool_id", "process_step", "target_yield_pct", "target_rationale")), as_index=False)
    .agg(n_wafers=("wafer_id", "count"), passed_wafers=("is_passed", "sum"), avg_temp_c=("chamber_temp_c", "mean"), total_cost_usd=("dynamic_cost_usd", "sum"))
)
equip_grp["actual_yield_pct"] = (100.0 * equip_grp["passed_wafers"] / equip_grp["n_wafers"]).round(2)
equip_grp["yield_gap_pct"] = (equip_grp["actual_yield_pct"] - equip_grp["target_yield_pct"]).round(2)
equip_grp = enrich_equipment_stats(equip_grp.sort_values("actual_yield_pct"))
worst_row = equip_grp.to_dict(orient="records").pop(0)

st.markdown(f"""
**Executive Summary:**
* **Key Finding:** **{worst_row['tool_id']}** ({worst_row['process_step']}) shows the lowest First-Pass Yield at **{worst_row['actual_yield_pct']}%** (95% Wilson CI: `{worst_row['ci_95_low']}%–{worst_row['ci_95_high']}%`, `z = {worst_row['z_vs_rest']}`, `p = {worst_row['p_value']}`).
* **Financial Impact:** Across **{tot_wafers:,}** filtered wafers, overall First-Pass Yield is **{overall_yield}%** with **${tot_cost:,.0f}** in combined scrap (`${scrap_unit_cost:,.0f}/unit`) and quarantine (`${quarantine_unit_cost:,.0f}/unit`) losses.
* **Recommended Action & Uncertainty:** *Hypothesis: Chamber thermal/RF calibration check recommended on {worst_row['tool_id']} and Night Shift handoffs* (validated on synthetic benchmark; real fab deployment requires tool-specific baseline calibration).
""")

k1, k2, k3, k4 = st.columns(4)
k1.metric("Filtered Wafers (n)", f"{tot_wafers:,}")
k2.metric("First-Pass Yield (FPY)", f"{overall_yield}%")
k3.metric("Total Cost Attribution", f"\\${tot_cost:,.0f}")
k4.metric("Primary Bottleneck", f"{worst_row['tool_id']}", delta=f"p = {worst_row['p_value']} vs. peer tools", delta_color="inverse")

tab_dash, tab_bridge, tab_sql = st.tabs(list(("1. Yield Attribution & SPC Control", "2. Three-Project Risk Calibration Bridge", "3. Read-Only SQL Workbench & Schema")))

with tab_dash:
    c1, c2 = st.columns(2)
    with c1:
        fig_tool = go.Figure()
        fig_tool.add_trace(go.Bar(
            x=equip_grp["tool_id"],
            y=equip_grp["actual_yield_pct"],
            error_y=dict(type="data", symmetric=False, array=equip_grp["ci_95_high"] - equip_grp["actual_yield_pct"], arrayminus=equip_grp["actual_yield_pct"] - equip_grp["ci_95_low"]),
            text=equip_grp["actual_yield_pct"].astype(str) + "%",
            textposition="outside",
            marker_color=list(("#EF553B" if p < 0.01 else "#00CC96" for p in equip_grp["p_value"])),
            name="Actual Yield (95% Wilson CI)",
        ))
        fig_tool.add_trace(go.Scatter(x=equip_grp["tool_id"], y=equip_grp["target_yield_pct"], mode="markers+lines", name="Target Yield SLA", line=dict(color="#636EFA", dash="dash")))
        fig_tool.update_layout(title="Equipment First-Pass Yield with 95% Wilson CI vs. Target", yaxis_range=list((65, 102)), height=350)
        st.plotly_chart(fig_tool, use_container_width=True)

    with c2:
        lot_grp = df_raw.groupby("lot_id", as_index=False).agg(n_inspected=("wafer_id", "count"), n_passed=("is_passed", "sum")).sort_values("lot_id")
        lot_grp["lot_yield_pct"] = (100.0 * lot_grp["n_passed"] / lot_grp["n_inspected"]).round(2)
        lot_grp = add_spc_control_limits(lot_grp)
        fig_spc = go.Figure()
        fig_spc.add_trace(go.Scatter(x=lot_grp["lot_id"], y=lot_grp["lot_yield_pct"], mode="lines+markers", name="Lot Yield (%)", line=dict(color="#636EFA")))
        fig_spc.add_trace(go.Scatter(x=lot_grp["lot_id"], y=lot_grp["spc_ucl_pct"], mode="lines", name="SPC UCL (+3σ)", line=dict(color="gray", dash="dot")))
        fig_spc.add_trace(go.Scatter(x=lot_grp["lot_id"], y=lot_grp["spc_lcl_pct"], mode="lines", name="SPC LCL (-3σ)", line=dict(color="#EF553B", dash="dash")))
        ooc = lot_grp.loc[lot_grp["out_of_control"]]
        if len(ooc) > 0:
            fig_spc.add_trace(go.Scatter(x=ooc["lot_id"], y=ooc["lot_yield_pct"], mode="markers", name="Out-of-Control Lot", marker=dict(color="red", size=10, symbol="diamond")))
        fig_spc.update_layout(title="SPC p-Chart: Lot Yield (n=25/lot) & 3σ Control Limits", yaxis_range=list((55, 105)), height=350)
        st.plotly_chart(fig_spc, use_container_width=True)

    c3, c4 = st.columns(2)
    with c3:
        def_only = df_raw.loc[df_raw["is_passed"] == 0]
        pareto_df = def_only.groupby("primary_defect_type", as_index=False).agg(incidents=("wafer_id", "count"), cost_usd=("dynamic_cost_usd", "sum")).sort_values("cost_usd", ascending=False)
        fig_par = px.bar(pareto_df, x="primary_defect_type", y="cost_usd", text_auto="$.2s", color="primary_defect_type", title="Defect Type Pareto Cost Attribution ($)")
        fig_par.update_layout(height=320, showlegend=False)
        st.plotly_chart(fig_par, use_container_width=True)
    with c4:
        hm_df = df_raw.groupby(list(("shift_label", "tool_id")), as_index=False).agg(yield_pct=("is_passed", lambda s: round(100.0 * s.mean(), 1)))
        piv = hm_df.pivot(index="shift_label", columns="tool_id", values="yield_pct")
        fig_hm = px.imshow(piv, text_auto=True, color_continuous_scale="RdYlGn", zmin=70, zmax=98, title="Shift × Equipment First-Pass Yield Heatmap (%)")
        fig_hm.update_layout(height=320)
        st.plotly_chart(fig_hm, use_container_width=True)

    st.subheader("Equipment Statistical Attribution & Target Rationale")
    st.dataframe(equip_grp, use_container_width=True, hide_index=True)
    st.download_button("⬇️ Download Filtered Warehouse Records (CSV)", data=df_raw.to_csv(index=False).encode("utf-8"), file_name="fab_yield_filtered.csv", mime="text/csv")

with tab_bridge:
    st.subheader("Three-Project Ecosystem Bridge: SiliconGuard Risk vs. Observed Optical Yield")
    st.caption("Validates whether upstream sensor risk deciles (SiliconGuard AI) align monotonically with downstream observed optical yield (Vision Inspector).")
    cal_df = df_raw.groupby("risk_decile", as_index=False).agg(n_wafers=("wafer_id", "count"), avg_predicted_risk_pct=("predicted_sensor_risk", lambda s: round(100.0 * s.mean(), 2)), observed_defect_rate_pct=("is_passed", lambda s: round(100.0 * (1.0 - s.mean()), 2)), observed_yield_pct=("is_passed", lambda s: round(100.0 * s.mean(), 2)), total_cost_usd=("dynamic_cost_usd", "sum")).sort_values("risk_decile")
    fig_cal = px.bar(cal_df, x="risk_decile", y=list(("avg_predicted_risk_pct", "observed_defect_rate_pct")), barmode="group", text_auto=".1f", labels={"risk_decile": "SiliconGuard Predicted Risk Decile", "value": "Rate (%)", "variable": "Metric"}, title="Risk Calibration Bridge: Predicted Sensor Risk vs. Observed Defect Rate")
    fig_cal.update_layout(height=350)
    st.plotly_chart(fig_cal, use_container_width=True)
    st.dataframe(cal_df, use_container_width=True, hide_index=True)

with tab_sql:
    st.subheader("Interactive Read-Only SQL Sandbox (`SQLite URI mode=ro`)")
    st.markdown("**Star Schema:** `dim_equipment(tool_id PK, process_step, chamber_model, target_yield_pct, target_rationale)` | `dim_shift(shift_id PK, shift_label, hours_window)` | `fact_wafer_inspection(wafer_id PK, lot_id, lot_size, tool_id FK, shift_id FK, inspected_at, chamber_temp_c, rf_power_w, predicted_sensor_risk, risk_decile, defects_found, primary_defect_type, defect_area_px, routing_decision, is_passed, estimated_cost_usd)`")
    templates = load_sql_templates()
    chosen = st.selectbox("Load Analytical SQL Query (`sql/*.sql`)", list(templates.keys()))
    user_sql = st.text_area("SQL Editor (Read-Only SELECT / WITH)", value=templates.get(chosen), height=230)
    if st.button("▶ Execute SQL Query", type="primary"):
        try:
            out_df = run_select_query(user_sql)
            st.success(f"Returned {len(out_df)} rows (read-only mode, max 500 rows).")
            st.dataframe(out_df, use_container_width=True, hide_index=True)
        except Exception as err:
            st.error(str(err))
